// Emulation of construct.Struct("field1"/construct.Int8ul, "field2"/construct.Int8ul).build(obj)
// Byte sequences are represented as plain arrays of numbers in the range 0-255.

export const INT8UL_FIELDS = [
  { name: 'field1', min: 0, max: 255 },
  { name: 'field2', min: 0, max: 255 },
];

export function buildStruct(obj) {
  const result = [];
  for (const field of INT8UL_FIELDS) {
    const value = obj[field.name];
    if (
      typeof value !== 'number' ||
      !Number.isInteger(value) ||
      value < field.min ||
      value > field.max
    ) {
      throw new RangeError(
        `Error in path (building) -> ${field.name}\nstruct '<B' error during building, given value ${value}`
      );
    }
    result.push(value);
  }
  return result;
}

