/**
 * Reproduces CPython's bytes.__repr__ (what print(b'...') shows) for a
 * byte sequence given as a plain array of integers (each 0-255).
 *
 * Rules (matching CPython's Objects/bytesobject.c bytes_repr):
 * - Quote selection: single quote by default; if the data contains byte 39
 *   (') and does NOT contain byte 34 ("), use double quotes instead.
 * - Escaping, applied per byte:
 *     backslash (92)          -> \\
 *     the active quote char   -> \<quote>
 *     tab (9)                 -> \t
 *     newline (10)            -> \n
 *     carriage return (13)    -> \r
 *     bytes 32-126 (printable)-> the literal ASCII character
 *     all other bytes         -> \xNN (lowercase two-digit hex)
 * - The result is wrapped as b<quote>...<quote>.
 *
 * @param {number[]} bytes - array of integers, each in [0, 255]
 * @returns {string} the exact repr string CPython would produce
 */
export function bytesRepr(bytes) {
  const hasSingleQuote = bytes.includes(39);
  const hasDoubleQuote = bytes.includes(34);
  const quote = hasSingleQuote && !hasDoubleQuote ? 34 : 39;
  const quoteChar = String.fromCharCode(quote);

  let out = 'b' + quoteChar;
  for (const b of bytes) {
    if (b === 92) {
      out += '\\\\';
    } else if (b === quote) {
      out += '\\' + quoteChar;
    } else if (b === 9) {
      out += '\\t';
    } else if (b === 10) {
      out += '\\n';
    } else if (b === 13) {
      out += '\\r';
    } else if (b >= 32 && b <= 126) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += quoteChar;
  return out;
}

