// Argument parser emulating Python argparse for the migrated script.
// Exposes parseArgs(argv) where argv is process.argv.slice(2).

const PROG = "test3.mjs";
const USAGE = `usage: ${PROG} [-h] --a A --b B`;

function printUsage(stream) {
  stream.write(USAGE + "\n");
}

function fail(message) {
  printUsage(process.stderr);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  printUsage(process.stdout);
  process.stdout.write("\n");
  process.stdout.write("options:\n");
  process.stdout.write("  -h, --help  show this help message and exit\n");
  process.stdout.write("  --a A\n");
  process.stdout.write("  --b B\n");
  process.exit(0);
}

// Mirrors Python int(str): surrounding whitespace stripped, an optional
// sign, then decimal digits with single underscores allowed between digits.
function parseIntLikePython(raw, optionName) {
  const trimmed = raw.trim();
  if (!/^[+-]?\d(?:_?\d)*$/.test(trimmed)) {
    fail(`argument ${optionName}: invalid int value: '${raw}'`);
  }
  const negative = trimmed.startsWith("-");
  const digits = trimmed.replace(/^[+-]/, "").replace(/_/g, "");
  const value = parseInt(digits, 10);
  return negative ? -value : value;
}

export function parseArgs(argv) {
  const values = { a: undefined, b: undefined };
  const seen = new Set();
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === "-h" || token === "--help") {
      printHelp();
    }

    let name = null;
    let inlineValue = null;

    if (token === "--a" || token === "--b") {
      name = token;
    } else if (token.startsWith("--a=")) {
      name = "--a";
      inlineValue = token.slice("--a=".length);
    } else if (token.startsWith("--b=")) {
      name = "--b";
      inlineValue = token.slice("--b=".length);
    }

    if (name === null) {
      unrecognized.push(token);
      i += 1;
      continue;
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
      i += 1;
    } else {
      if (i + 1 >= argv.length) {
        fail(`argument ${name}: expected one argument`);
      }
      raw = argv[i + 1];
      i += 2;
    }

    const key = name === "--a" ? "a" : "b";
    values[key] = parseIntLikePython(raw, name);
    seen.add(name);
  }

  const missing = [];
  if (!seen.has("--a")) missing.push("--a");
  if (!seen.has("--b")) missing.push("--b");
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(", ")}`);
  }

  if (unrecognized.length > 0) {
    fail(`unrecognized arguments: ${unrecognized.join(" ")}`);
  }

  return { a: values.a, b: values.b };
}

