  try {
    buildStruct({ field1: 0, field2: v });
    console.log(`FAIL: no throw for ${String(v)}`);
  } catch (e) {
    console.log(`${String(v)} -> ${e.constructor.name}: ${JSON.stringify(e.message)}`);
  }
}
