// Entry point mirroring the original Python script's main():
// parse --a/--b, build the two-byte struct, print the bytes repr.

import { fileURLToPath } from 'node:url';
import { parseArgs } from './lib/argParser.mjs';
import { buildStruct } from './lib/struct.mjs';
import { bytesRepr } from './lib/pythonBytes.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2));
  let data;
  try {
    data = buildStruct({ field1: args.a, field2: args.b });
  } catch (err) {
    if (err instanceof RangeError) {
      process.stderr.write('Traceback (most recent call last):\n');
      process.stderr.write(`construct.core.RangeError: ${err.message}\n`);
      process.exit(1);
    }
    throw err;
  }
  console.log(bytesRepr(data));
}

const isMainModule =
  process.argv[1] !== undefined &&
  fileURLToPath(import.meta.url) === process.argv[1];

if (isMainModule) {
  main();
}

